package com.zhitu.controller;
import com.zhitu.common.ApiResponse;import com.zhitu.dto.Requests;import com.zhitu.service.TrustedAuditService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/audits") public class AuditController {private final TrustedAuditService service;public AuditController(TrustedAuditService s){service=s;}@GetMapping("/pending")public ApiResponse<List<Map<String,Object>>>pending(){return ApiResponse.ok(service.pending());}@PostMapping("/{type}/{id}/decision")public ApiResponse<Map<String,Object>>decision(@PathVariable String type,@PathVariable long id,@Valid @RequestBody Requests.AuditDecision r){return ApiResponse.ok(service.decision(type,id,r.action(),r.reviewer(),r.comment(),r.patch()));}@GetMapping("/history")public ApiResponse<List<Map<String,Object>>>history(){return ApiResponse.ok(service.history());}}
